export function gameStatusText(g){if(['FINAL','FINAL/OT'].includes(g.bottomStatus))return g.quarter==='OT'?'FINAL/OT'+(Number(g.overtimePeriod)>1?g.overtimePeriod:''):'FINAL';return g.bottomStatus&&g.bottomStatus!=='LIVE'?g.bottomStatus:'';}
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const formations={'4-3-4':[4,3,4],'3-4-4':[3,4,4],'4-2-5':[4,2,5],'3-3-5':[3,3,5],'5-2-4':[5,2,4],'4-1-6':[4,1,6]};
export const defensePositions={"4-3-4":["DL","DL","DL","DL","LB","LB","LB","CB","FS","SS","CB"],"3-4-4":["DL","DL","DL","LB","LB","LB","LB","CB","FS","SS","CB"],"4-2-5":["DL","DL","DL","DL","LB","LB","CB","CB","FS","SS","CB"],"3-3-5":["DL","DL","DL","LB","LB","LB","CB","CB","FS","SS","CB"],"5-2-4":["DL","DL","DL","DL","DL","LB","LB","CB","FS","SS","CB"],"4-1-6":["DL","DL","DL","DL","LB","CB","CB","FS","SS","CB","CB"]};
export const offensePositions=['LT','LG','C','RG','RT','WR','WR','TE','RB','WR'];
export const graphicNames={referee:'Referee',tiers:'Upcoming matchups · three tiers',standings:'Division standings',transition:'Broadcast transition',scoringdrive:'Scoring drive',scorebug:'Scorebug',qbstats:'Player side stats',none:'No graphic',matchup:'Matchup banner',offense:'Offensive lineup',defense:'Defensive lineup',quarterback:'QB introduction',player:'Player spotlight',coach:'Coaching staff',lowerthird:'Lower third',stats:'Player statistics',teamstats:'Team comparison',event:'Scoring & alerts',period:'Period summary',final:'Final-score banner',upcoming:'Upcoming game',announcers:'Commentators',sponsor:'Sponsor promo',weather:'Weather',reporter:'Reporter nameplate',situation:'Situational stats',break:'Commercial break'};
export function clockSeconds(c,now=Date.now()/1000){return Math.max(0,Math.ceil(c.remaining-(c.running?now-c.anchor:0)));}
export function clockText(c,now){const sec=clockSeconds(c,now);return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;}
function teamStyle(t){return `--team:${esc(t.color)};--secondary:${esc(t.secondary)}`;}
function logo(t){return t.logo?`<img class="team-logo" src="${esc(t.logo)}" alt="${esc(t.name)}">`:`<span class="team-monogram">${esc(t.abbr)}</span>`;}
function player(t,id){return t.roster.find(p=>p.id===id)||{id:'',name:'',number:'',position:'',photo:'',stats:{}};}
function portrait(p){return p.photo?`<img class="portrait" src="${esc(p.photo)}" alt="${esc(p.name)}">`:`<div class="jersey-number">${esc(p.number)}</div>`;}
function bars(n){return `<div class="timeout-bars" aria-label="${n} timeouts remaining">${[0,1,2].map(i=>`<i class="${i<n?'available':''}"></i>`).join('')}</div>`;}
function teamWing(t,side,g){return `<div class="team-wing ${side}" style="${teamStyle(t)}"><span class="record">${esc(t.record)}</span><div class="bug-logo-crop">${logo(t)}</div>${bars(g.timeouts[side])}</div>`;}
function scorebug(s){const g=s.game,b=s.branding,penalty=s.program.graphic.type==='event'&&s.program.graphic.event==='FLAG'&&s.program.graphic.flagVariant!=='generic'?s.program.graphic.team:'';return `<div class="bug-wrap ${penalty?'penalty-'+penalty:''} ${g.showInfo===false?'info-hidden':''}" style="bottom:${b.bugBottom}px;--bug-scale:${b.bugScale}"><div class="flag-tab ${g.flag?'on':''}"><svg class="flag-face" viewBox="0 0 420 70" aria-hidden="true"><path fill="#101317" d="M55 0H365L420 70H0Z"/><path fill="#ffdc16" d="M148 0H272L326 70H94Z"/><path class="flag-stripes" fill="#ffdc16" d="M112 0H132L78 70H58Z M288 0H308L362 70H342Z"/><path fill="#d6dee1" d="M55 0H365L368 3H52Z"/></svg><svg class="flag-rim-outline" viewBox="0 0 420 70" aria-hidden="true"><path d="M55 1H365L419 69H1Z"/></svg><span class="flag-label">FLAG</span><span class="flag-outline" aria-hidden="true">FLAG</span></div><div class="scorebug"><div class="bug-top-rail-reveal" aria-hidden="true"><img src="./scorebug-top-rails.svg?v=20260923-controls105" alt=""></div><div class="bug-intro-mask" aria-hidden="true"><svg viewBox="0 0 920 200" preserveAspectRatio="none"><defs><linearGradient id="helmet-metal" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#adb2b5"/><stop offset=".22" stop-color="#45494c"/><stop offset=".64" stop-color="#17191b"/><stop offset="1" stop-color="#777b80"/></linearGradient></defs><path fill="#020304" d="M0 0H920V200H0Z"/><g fill="url(#helmet-metal)" stroke="#555b60" stroke-width="3"><path d="M30 0H165L209 200H137L94 123L69 16L83 160L114 200H55L26 74Z"/><path d="M890 0H755L711 200H783L826 123L851 16L837 160L806 200H865L894 74Z"/><path d="M220 0H700L657 101Q623 161 569 174L548 200H372L351 174Q297 161 263 101Z"/></g><path fill="#030405" d="M251 0H669L649 73Q578 108 460 103Q342 108 271 73Z"/><path fill="#e2e6e7" stroke="#777e82" stroke-width="3" d="M278 56L348 78L424 85L460 99L496 85L572 78L642 56L617 88L562 108L489 108L460 114L431 108L358 108L303 88Z"/><path fill="#050607" d="M302 111Q368 130 426 124L460 131L494 124Q552 130 618 111L594 151Q547 176 498 167L483 153H437L422 167Q373 176 326 151Z"/><path fill="#8c9397" d="M396 182L426 174H494L524 182L542 200H378Z"/><g fill="none" stroke="#c4c9cc" stroke-width="6"><path d="M193 0L228 133L269 200M727 0L692 133L651 200"/></g></svg></div><div class="bug-electric" aria-hidden="true"><svg viewBox="0 0 100 220" preserveAspectRatio="none"><g class="arc arc-a"><path d="M52 0L37 19L53 27L24 50L42 61L31 78L65 100L43 122L54 146L26 162L47 183L34 202L53 220 M65 100L87 87L100 110"/></g><g class="arc arc-b"><path d="M31 0L50 22L30 42L61 57L42 74L55 90L29 109L62 129L44 151L70 173L42 197L49 220 M61 57L83 43L98 65 M29 109L6 102L0 129 M70 173L89 181L99 169"/></g><g class="arc arc-c"><path d="M65 0L43 14L57 33L35 48L56 68L27 85L49 112L35 135L63 148L41 174L53 196L29 220 M27 85L9 67L0 79 M63 148L87 135L100 155"/></g></svg></div><div class="bug-metal"><span class="bug-possession-rail ${g.possession==='home'?'home':''} ${g.possession==='none'?'off':''}" aria-hidden="true"></span><img class="bug-frame-rails" src="./scorebug-rails.svg?v=20260923-controls105" alt="" aria-hidden="true"><div class="bug-body">${teamWing(s.teams.away,'away',g)}<div class="score-center" style="--away-color:${esc(s.teams.away.color)};--home-color:${esc(s.teams.home.color)}"><span class="possession-cap ${g.possession==='home'?'cap-home':''} ${g.possession==='none'?'cap-hidden':''}" role="img" aria-label="${esc(g.possession==='none'?'No possession':s.teams[g.possession]?.name+' possession')}" aria-hidden="${g.possession==='none'}"></span><div class="score-row">${['away','home'].map(side=>`<b data-score-side="${side}">${g.scores[side]}</b>`).join('')}</div><div style="--status-width:${Math.min(470,Math.max(240,gameStatusText(g).length*23+48))}px" class="information ${g.showDownDistance===false?'down-hidden':''} ${g.bottomStatus&&g.bottomStatus!=='LIVE'?'status-mode':''}"><span>${esc(g.quarter==='OT'?(Number(g.overtimePeriod)>1?'OT/'+g.overtimePeriod:'OT'):g.quarter)}</span><span data-game-clock>${clockText(g.clock)}</span><span class="play-clock ${clockSeconds(g.playClock)<=5?'urgent':''} ${g.showPlayClock?'':'play-hidden'}" data-play-clock>${clockSeconds(g.playClock)}</span><span class="down" style="${g.down.endsWith(' DOWN')?'':String(g.down+' & '+g.distance).length>10?'font-size:32px':String(g.down+' & '+g.distance).length>8?'font-size:38px':''}"><span class="down-current">${esc(g.down)}${(['PAT','KICK'].includes(g.down)||g.down.endsWith(' DOWN'))?'':` & ${esc(g.distance)}`}</span></span><span class="game-status">${esc(gameStatusText(g))}</span></div></div>${teamWing(s.teams.home,'home',g)}</div></div></div><div class="ball-marker ${g.showBallPosition?'':'ball-hidden'}">BALL ON ${esc(g.ballOn)}</div></div>`;}
function panelHeader(s,title,sub,t){return `<div class="graphic-heading"><div class="heading-title">${t?`<div class="heading-mark" style="${teamStyle(t)}">${logo(t)}</div>`:''}<div><div class="eyebrow">${esc(sub||s.branding.competition)}</div><h1>${esc(title)}</h1></div></div><div class="network">${esc(s.branding.network)}</div></div>`;}
function footer(s,text){return `<div class="graphic-footer"><span>${esc(text||s.branding.venue)}</span><span>${esc(s.branding.competition)}</span></div>`;}
function lineup(s,c){const t=s.teams[c.team],lu=s.lineups[c.team],off=c.type==='offense',sizes=off?[5,5]:formations[lu.formation],group=Math.min(Number(c.lineupGroup)||0,sizes.length-1),start=sizes.slice(0,group).reduce((a,b)=>a+b,0),ids=lu[off?'offense':'defense'],positions=off?offensePositions:defensePositions[lu.formation],title=(off?['OFFENSIVE LINE','BACKS AND RECEIVERS']:['DEFENSIVE LINE','LINEBACKERS','SECONDARY'])[group],names=c.lineupPhase==='players';return `<section class="lineup-ribbon" style="${teamStyle(t)}"><div class="lineup-team-tab">${esc(t.shortName||t.name)} ${off?'OFFENSE':'DEFENSE'}</div><div class="lineup-ribbon-frame"><div class="lineup-ribbon-face">${names?`<div class="lineup-names">${ids.slice(start,start+sizes[group]).map((id,i)=>{const p=player(t,id),parts=p.name.trim().split(/\s+/),first=parts.length>1?parts.shift():'',last=parts.join(' ');return `<div class="lineup-player-panel" style="--name-delay:${i*80}ms;--surname-length:${Math.max(8,last.length)}"><span class="lineup-position"><span>${esc(positions[start+i])}</span><span>${esc(p.number)}</span></span><div class="lineup-name-stack"><small><span class="lineup-copy lineup-first">${esc(first)}</span></small><strong><span class="lineup-copy">${esc(last)}</span></strong><span class="lineup-rookie">${p.rookie?'ROOKIE':''}</span></div></div>`}).join('')}</div>`:`<h1>${title}</h1>`}</div></div><div class="lineup-ribbon-logo">${logo(t)}</div></section>`;}

function matchup(s,c){const final=c.type==='finalboard',period=c.type==='period';return `<section class="full-graphic matchup">${panelHeader(s,final?'FINAL SCORE':period?c.period:'TONIGHT’S MATCHUP',s.branding.competition)}<div class="matchup-teams">${['away','home'].map(side=>{const t=s.teams[side];return `<div class="matchup-team" style="${teamStyle(t)}"><div class="matchup-logo">${logo(t)}</div><h2>${esc(t.name)}</h2><p>${esc(t.record)}</p>${final||period?`<div class="large-score">${s.game.scores[side]}</div>`:''}</div>`}).join('')}<div class="versus">${final||period?'—':'VS'}</div></div>${footer(s,s.branding.venue)}</section>`;}
export function passerRating(comp,att,yards,td,int){
 const v=[comp,att,yards,td,int].map(Number);[comp,att,yards,td,int]=v;
 if(v.some(x=>!Number.isFinite(x))||att<=0||comp<0||comp>att||td<0||td>comp||int<0||int>att)return null;
 const cap=x=>Math.max(0,Math.min(2.375,x));
 return Number(((cap((comp/att-.3)*5)+cap((yards/att-3)*.25)+cap(td/att*20)+cap(2.375-int/att*25))/6*100).toFixed(1));
}
function qbSeason(c){const comp=Number(c.qbSeasonComp)||0,att=Number(c.qbSeasonAtt)||0,yards=Number(c.qbSeasonYards)||0,td=Number(c.qbSeasonTD)||0,int=Number(c.qbSeasonINT)||0,rating=passerRating(comp,att,yards,td,int);return `<div class="qb-feature qb-season"><header>${esc(c.qbSeasonLabel||'SEASON STATS')}</header><dl>${[['COMP/ATT',comp+'/'+att],['YDS',yards],['TD',td],['INT',int],['PASSER RATING',rating===null?'—':rating.toFixed(1)]].map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl></div>`;}
function quarterback(s,c){const t=s.teams[c.team],p=player(t,s.lineups[c.team].quarterback),other=s.teams[c.team==='away'?'home':'away'],stat=Object.entries(p.stats)[0]||['STATS','—'],parts=p.name.trim().split(/\s+/),first=parts.length>1?parts.shift():'',last=parts.join(' ');return `<section class="qb-sidebar" style="${teamStyle(t)}"><div class="qb-top-logo">${logo(t)}</div><div class="qb-cutout">${portrait(p)}</div><div class="qb-sidebar-name"><small>${esc(first)}</small><strong>${esc(last)}</strong></div>${c.qbIntroMode==='season'?qbSeason(c):`<div class="qb-feature"><b>${esc(c.qbValue||stat[1])}</b><strong>${esc(c.qbLabel||stat[0])}</strong><p class="${c.qbContextYellow?'qb-context-yellow':''}">${esc(c.qbDetail||'SEASON STATS')}</p></div>`}</section>`;}
function reporter(s,c){return `<section class="reporter-nameplate"><div class="reporter-network">${networkMark(s)}</div><h1>${esc(c.reporterName||'REPORTER NAME')}</h1></section>`;}
function coachDock(s,c){const t=s.teams[c.team],staff=(t.staff||[]).find(x=>x.id===c.staffId);if(staff)c={...c,staffName:staff.name,staffRole:staff.role,staffDetail:staff.detail};return `<section class="staff-anchor dock-${esc(c.team)}" style="${teamStyle(t)};bottom:${Number(s.branding.bugBottom)}px;--dock-scale:${Number(s.branding.bugScale)}"><div class="staff-reveal"><div class="staff-tab">${esc(c.staffRole||'HEAD COACH')}</div><div class="staff-plate"><h1>${esc(c.staffName||t.coach)}</h1><p>${esc(c.staffDetail||t.abbr+' COACHING STAFF')}</p></div></div></section>`;}
function weather(s,c){return `<section class="weather-card"><header><h1>WEATHER</h1><p>${esc(s.teams.away.shortName||s.teams.away.abbr)} vs ${esc(s.teams.home.shortName||s.teams.home.abbr)}</p></header><dl>${[['TEMP',c.weatherTemp||'—'],['WINDS',c.weatherWind||'—'],['FORECAST',c.weatherForecast||'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>`;}
function playerCard(s,c){const t=s.teams[c.team],lu=s.lineups[c.team],p=player(t,c.type==='quarterback'?lu.quarterback:c.playerId);return `<section class="player-graphic" style="${teamStyle(t)}"><div class="player-card-photo">${portrait(p)}</div><div class="player-card-info"><div class="eyebrow">${esc(t.name)} / ${esc(c.type==='quarterback'?'QUARTERBACK':p.position)}</div><h1><span>${esc(p.number)}</span> ${esc(p.name)}</h1><div class="player-stats">${Object.entries(p.stats).map(([label,val])=>`<div><b>${esc(val)}</b><span>${esc(label)}</span></div>`).join('')}</div></div><div class="card-team-logo">${logo(t)}</div></section>`;}
function lower(s,c){const t=s.teams[c.team];return `<section class="lower-third" style="${teamStyle(t)}"><div class="lower-mark">${logo(t)}</div><div><div class="eyebrow">${esc(c.type==='coach'?t.name:c.subtitle)}</div><h1>${esc(c.type==='coach'?t.coach:c.title)}</h1>${c.type==='coach'?'<p>HEAD COACH</p>':''}</div><div class="network">${esc(s.branding.network)}</div></section>`;}
function compare(s,c){return `<section class="full-graphic comparison">${panelHeader(s,'TEAM COMPARISON',s.branding.competition)}<div class="compare-head">${logo(s.teams.away)}<span>${esc(s.teams.away.name)}</span><span>${esc(s.teams.home.name)}</span>${logo(s.teams.home)}</div><div class="stat-table">${c.stats.map(r=>`<div><b>${esc(r.away)}</b><span>${esc(r.label)}</span><b>${esc(r.home)}</b></div>`).join('')}</div>${footer(s)}</section>`;}
function rosterGraphic(s,c){const t=s.teams[c.team],page=Math.min(c.rosterPage||1,Math.ceil(t.roster.length/30));return `<section class="full-graphic roster-graphic" style="${teamStyle(t)}">${panelHeader(s,'TEAM ROSTER',t.name,t)}<div class="roster-columns">${t.roster.slice((page-1)*30,page*30).map(p=>`<div class="roster-name"><b>${esc(p.number)}</b><strong>${esc(p.name)}</strong><span>${esc(p.position)}</span></div>`).join('')}</div>${footer(s,`${t.name} • PAGE ${page} OF ${Math.ceil(t.roster.length/30)}`)}</section>`;}
function touchdown(s,c,t,p,variant){
 const fragments=Array.from({length:24},(_,i)=>{const angle=i*137.508*Math.PI/180,reach=170+(i%6)*68;return `<i style="--i:${i};--dx:${Math.round(Math.cos(angle)*reach)}px;--dy:${Math.round(Math.sin(angle)*reach*.6)}px;--turn:${Math.round(angle*180/Math.PI)%360}deg;--blade:${80+i%5*25}px"></i>`;}).join('');
 return `<section class="td-sequence" data-variant="${esc(variant)}" style="${teamStyle(t)};--td-cover-height:${Math.max(206,Number(s.branding.bugBottom)+200*Number(s.branding.bugScale)+4)}px"><div class="td70-rails"><i></i><i></i><i></i></div><div class="td70-portrait">${variant==='player'&&p.photo?portrait(p):variant!=='generic'?logo(t):''}</div><h1 class="td70-title" aria-label="TOUCHDOWN">${[...'TOUCHDOWN'].map((letter,i)=>`<span aria-hidden="true" style="--i:${i}">${letter}</span>`).join('')}</h1>${variant==='generic'?'':`<div class="td70-name">${variant==='player'?`<b>${esc(p.number)}</b><strong>${esc(p.name)}</strong>`:`<strong>${esc(t.shortName||t.name)}</strong>`}</div>`}<div class="td70-burst" aria-hidden="true">${fragments}</div><svg class="td70-electric" viewBox="0 0 920 480" aria-hidden="true"><path d="M0 83L55 91 76 73 105 96 125 90 137 134 169 129 193 150 214 135 260 163 275 156 302 194 285 207 315 246 352 235 370 280 397 273 432 318 416 328 470 377M137 134L128 159 155 185M302 194L328 180 357 201M370 280L339 298 359 330"/></svg></section>`;
}
function event(s,c){const t=s.teams[c.team||'away'],p=player(t,c.penaltyPlayer||c.playerId),variant=c.flagVariant||'team';
if(c.event==='FLAG')return `<section class="situation-group"><div class="situation-anchor dock-${esc(c.team||'away')} penalty-panel ${variant==='player'?'with-player':''}" style="${teamStyle(t)};bottom:${s.branding.bugBottom}px;--dock-scale:${s.branding.bugScale}"><div class="situation-reveal"><h1>${esc(c.penaltyType==='CUSTOM'?c.penaltyDetail:c.penaltyType||'FLAG')}</h1>${variant==='player'?`<p><b>#${esc(p.number)}</b> ${esc(p.name)}</p>`:c.penaltyDetail&&c.penaltyType!=='CUSTOM'?`<p>${esc(c.penaltyDetail)}</p>`:''}</div></div></section>`;
if(c.event==='TOUCHDOWN')return touchdown(s,c,t,p,variant);
const label=c.event==='TIMEOUT'?`${['','1ST','2ND','3RD'][Number(c.timeoutNumber)||Math.max(1,Math.min(3,3-Number(s.game.timeouts[c.team||'away'])))]} TIMEOUT`:c.event;
return `<section class="situation-group"><div class="situation-anchor dock-${esc(c.team||'away')} attempt-tag alert-tab ${c.event==='UNDER REVIEW'?'review-tab':''}" style="${teamStyle(t)};bottom:${s.branding.bugBottom}px;--dock-scale:${s.branding.bugScale}"><div class="situation-reveal"><h1>${esc(label)}</h1>${c.subtitle?`<p>${esc(c.subtitle)}</p>`:''}</div></div></section>`;}

function upcoming(s,c){return `<section class="full-graphic upcoming">${panelHeader(s,'COMING UP NEXT',s.branding.competition)}<div class="upcoming-content"><h2>${esc(c.nextAway)}</h2><span>VS</span><h2>${esc(c.nextHome)}</h2><p>${esc(c.nextTime)}</p></div>${footer(s)}</section>`;}
function networkMark(s){return s.branding.networkLogo?`<img src="${esc(s.branding.networkLogo)}" alt="${esc(s.branding.network)}">`:`<span>${esc(s.branding.network)}</span>`;}
export function matchupVenue(s,c){return {stadium:(!c.title||c.title==='FRIDAY NIGHT FOOTBALL'?s.branding.venue:c.title)||'',location:(!c.subtitle||/^Live from /i.test(c.subtitle)?[s.branding.city,s.branding.stateAbbr].filter(Boolean).join(', '):c.subtitle)};}
function resultBanner(s,c){const final=c.type==='final',isBreak=c.type==='break',showScores=final||isBreak,venue=matchupVenue(s,c);return `<section class="result-banner ${showScores?'final-banner':'venue-banner'} ${isBreak?'break-banner':''}" style="--away-color:${esc(s.teams.away.color)};--home-color:${esc(s.teams.home.color)}"><div class="result-metal"><div class="result-surface"></div></div><div class="result-badge">${networkMark(s)}</div>${['away','home'].map(side=>{const t=s.teams[side];return `<div class="result-team ${side}" style="${teamStyle(t)}"><div class="result-logo">${logo({...t,logo:t.heroLogo||t.logo})}</div><div class="result-name">${esc(t.shortName||t.name)}</div>${isBreak?`<span class="break-record">${esc(t.record||'')}</span>`:''}</div>`}).join('')}<div class="result-center">${showScores?`<div class="result-scores"><b>${s.game.scores.away}</b><i></i><b>${s.game.scores.home}</b></div>`:`<div class="result-venue">${esc(venue.stadium)}</div>`}<div class="result-status">${isBreak?breakClock(s):esc(final?gameStatusText({...s.game,bottomStatus:'FINAL'}):venue.location)}</div></div></section>`;}
function announcers(s,c){return `<section class="announcer"><div class="metal-rail rail-left"></div><div class="metal-rail rail-right"></div><div class="announcer-frame"><div class="announcer-panel"><div class="announcer-person"><h1>${esc(c.leftName||'PLAY-BY-PLAY')}</h1><p>${esc(c.leftRole||'')}</p></div><div class="announcer-person"><h1>${esc(c.rightName||'ANALYST')}</h1><p>${esc(c.rightRole||'')}</p></div></div></div></section>`;}
function sponsor(s,c){const b=s.branding;return `<section class="sponsor-promo" style="--sponsor:${esc(b.sponsorColor||'#101349')}"><div class="sponsor-panel"><div class="sponsor-brand">${b.sponsorLogo?`<img src="${esc(b.sponsorLogo)}" alt="${esc(b.sponsorName)}">`:`<strong>${esc(b.sponsorName||'YOUR SPONSOR')}</strong>`}</div><h1>${esc(c.sponsorTitle||'POSTGAME')}</h1><p>${esc(c.sponsorSubtitle||'')}</p><div class="sponsor-next">▸ ${esc(c.sponsorNext||'COMING UP NEXT')}</div></div></section>`;}
function qbPassingStats(c){const values=[['COMP/ATT',Number(c.qbAtt)>0?`${Number(c.qbComp)||0}/${Number(c.qbAtt)}`:null],['YDS',Number(c.qbYards)||null],['TD',Number(c.qbTD)||null],['INT',Number(c.qbINT)||null]];return values.filter(([,v])=>v!==null);}
function sidePlayerStats(c){return [[c.sideStatsLayout?.startsWith('receiving')?'REC':'RUSH',Number(c.sideCount)||null],['YDS',Number(c.sideYards)||null],['TD',Number(c.sideTD)||null]].filter(([,v])=>v!==null);}
export function qbLiveStats(c){const layout=c.sideStatsLayout||'qb';return [...(layout==='qb'||layout.endsWith('-qb')?qbPassingStats(c):[]),...(layout!=='qb'?sidePlayerStats(c):[])];}

export function qbShortName(name){const parts=String(name||'').trim().split(/\s+/);return parts.length>1?parts[0][0]+'. '+parts.slice(1).join(' '):parts[0];}
function qbLive(s,c){const side=c.team||'away',team=s.teams[side],layout=c.sideStatsLayout||'qb',rows=[];if(layout!=='qb'){const stats=sidePlayerStats(c);if(stats.length)rows.push({p:player(team,c.sidePlayerId),stats});}if(layout==='qb'||layout.endsWith('-qb')){const stats=qbPassingStats(c);if(stats.length)rows.push({p:player(team,s.lineups[side].quarterback),stats});}return `<div class="qb-live-anchor dock-${esc(side)}" style="${teamStyle(team)};bottom:${s.branding.bugBottom}px;--bug-scale:${s.branding.bugScale}" data-motion="${esc(c.transition||'auto')}"><div class="qb-live-bar side-stat-stack" style="--side-rows:${rows.length}">${rows.map(row=>`<div class="side-stat-row"><div class="qb-live-content"><div class="side-stat-copy"><strong class="qb-live-name">${esc(qbShortName(row.p.name))}</strong><div class="qb-live-values">${row.stats.map(([label,value])=>`<span><b>${esc(value)}</b>${label==='COMP/ATT'?'':`<small>${label}</small>`}</span>`).join('')}</div></div></div></div>`).join('')}</div></div>`;}


function situation(s,c){const kind=c.situationKind||'fieldgoal',side=c.team||'away',other=side==='away'?'home':'away';const anchor=(team,body,variant)=>`<div class="situation-anchor dock-${team} ${variant}" style="${teamStyle(s.teams[team])};bottom:${s.branding.bugBottom}px;--dock-scale:${s.branding.bugScale}"><div class="situation-reveal">${body}</div></div>`;let panels='';if(kind==='punt'){for(const team of ['away','home']){const punting=team===side,t=s.teams[team],id=punting?(c.leftName||s.lineups[team].specialTeams?.punter):(c.rightName||s.lineups[team].specialTeams?.puntReturner),p=t.roster.find(x=>x.id===id)||t.roster.find(x=>x.position===(punting?'P':'WR'))||{name:'',number:'',position:''};panels+=anchor(team,`<h1><small>${esc(p.number)} ${esc(p.position)}</small> ${esc(p.name)}</h1><p>${esc(t.shortName||t.abbr)} ${punting?'PUNTER':'RETURNER'}</p>`,'punt-panel');}}else if(kind==='fieldgoal'){const distance=Number(c.attemptDistance)||parseInt(c.situationDetail)||0;panels=anchor(side,`<h1>${distance?`<b>${distance}</b> YD `:''}ATTEMPT</h1>`,'attempt-tag');}else if(kind==='kicker'){const t=s.teams[side],k=t.roster.find(x=>x.id===(c.kickerId||s.lineups[side].specialTeams?.kicker));panels=anchor(side,`${k?.photo?`<div class="kicker-photo">${portrait(k)}</div>`:''}<div class="kicker-context">${esc(c.kickerContext||'THIS SEASON')}</div><h1><small>${esc(k?.number||'')} K</small> ${esc(k?.name||'SELECT KICKER')}</h1><p><b>${Number(c.kickerMade)||0}/${Number(c.kickerAttempts)||0}</b><span>FGs</span><b>${Number(c.kickerLong)||0}</b><span>LONG</span></p>`,'kicker-panel');}else{const attempts=Number(c.attempts)||0,made=Number(c.conversions)||0,distances=Array.isArray(c.conversionDistances)?c.conversionDistances:[],avg=distances.length?(distances.reduce((sum,d)=>sum+Number(d),0)/distances.length).toFixed(1):'—';const layout=c.conversionLayout||'count';panels=anchor(side,`<h1>${kind==='fourth'?'4TH':'3RD'} DOWN CONVERSIONS</h1><p class="conversion-layout-${esc(layout)}">${layout==='percentage'?`<b>${attempts?'%'+(made/attempts*100).toFixed(1):'%0.0'}</b><span>${esc(c.situationDetail)}</span>`:layout==='count'?`<b class="conversion-made">${made} <small>FOR</small> ${attempts}</b><span>AVG YDS TO GO <strong>${avg}</strong></span>`:`<b>${attempts?'%'+(made/attempts*100).toFixed(1):'%0.0'}</b><span class="conversion-count">${made}/${attempts}<small>MADE/ATT</small></span><span class="conversion-average">${avg}<small>AVG TO GO</small></span>`}</p>`,'conversion-panel');}return `<section class="situation-group">${panels}</section>`;}

function scoringDrive(s,c){const t=s.teams[c.team||'away'];return `<section class="drive-card" style="${teamStyle(t)}"><div class="drive-surface"><header><div class="drive-logo">${logo(t)}</div><h1>SCORING DRIVE</h1></header><div class="drive-body"><p>${Number(c.drivePlays)||0} PLAYS, ${Number(c.driveYards)||0} YDS, ${esc(c.driveTime||'0:00')}</p><strong>${esc(c.driveResult||'SCORING PLAY')}</strong>${c.driveNote?`<small>▸ ${esc(c.driveNote)}</small>`:''}</div></div></section>`;}
function breakClock(s){const status=gameStatusText(s.game);return status?esc(status):`${esc(s.game.quarter==='OT'?(Number(s.game.overtimePeriod)>1?'OT/'+s.game.overtimePeriod:'OT'):s.game.quarter+' QTR')} <span data-game-clock>${clockText(s.game.clock)}</span>`;}
function commercial(s,c){const mode=c.breakLayout||'small';if(mode==='stinger')return broadcastTransition(s,{...c,transitionStyle:'network'});if(mode==='small')return `<section class="commercial-mini"><div class="mini-content"><header>${networkMark(s)}${s.branding.sponsorLogo?`<img class="mini-sponsor" src="${esc(s.branding.sponsorLogo)}" alt="${esc(s.branding.sponsorName||'Sponsor')}">`:''}</header>${['away','home'].map(side=>`<div class="mini-team" style="${teamStyle(s.teams[side])}"><div>${logo(s.teams[side])}</div><b>${s.game.scores[side]}</b></div>`).join('')}<footer>${breakClock(s)}</footer></div><div class="mini-intro" aria-hidden="true"><div class="mini-badge">${secondaryMark(s)}</div></div></section>`;return resultBanner(s,c);}
function secondaryMark(s){const src=s.branding.secondaryLogo||s.branding.networkLogo;return src?`<img class="secondary-mark" src="${esc(src)}" alt="Broadcast logo">`:networkMark(s);}
function referee(s,c){const parts=String(c.refereeExperience||'').trim().split(/\s+/),first=parts.shift()||'',ordinal=/^\d+(ST|ND|RD|TH)?$/i.test(first);return `<section class="referee-card bevel-card"><div class="referee-face"><div><h1>${esc(c.refereeName)}</h1><p>${esc(c.refereeRole||'REFEREE')}${first?` - ${ordinal?`<em>${esc(first)}</em>`:esc(first)} ${esc(parts.join(' '))}`:''}</p></div></div><div class="referee-rails"></div><div class="referee-mark"><img class="secondary-mark" src="./assets/league/nfl.png" alt="NFL"></div></section>`;}

function tiers(s,c){return `<section class="tiers-card bevel-card upcoming-tiers" style="--away-color:#102b49;--home-color:#102b49"><div class="tiers-face"><div class="tiers-copy">${[1,2,3].map(n=>`<div class="tier tier-${n} ${c['tier'+n+'Yellow']?'yellow':''}"><strong>${esc(c['tier'+n+'Away']||'')}<span class="matchup-at"> AT </span>${esc(c['tier'+n+'Home']||'')}</strong><small>${esc(c['tier'+n]||'')}</small></div>`).join('')}<footer>${esc(c.tierBottom||'')}</footer></div></div></section>`;}
function standings(s,c){const division=c.divisionId||c.divisionTitle||'NFC EAST',conference=division.startsWith('AFC')?'AFC':'NFC';return `<section class="standings-card conference-${conference.toLowerCase()}"><div class="standings-face"><header><h1>${esc(division)}</h1></header><div class="division-records">${(c.standingsRows||[]).slice(0,4).map(r=>`<div><b>${esc(r.name)}</b><strong>${Number(r.wins)||0}-${Number(r.losses)||0}${Number(r.ties)?'-'+Number(r.ties):''}</strong></div>`).join('')}</div></div><img class="conference-logo" src="./assets/league/${conference.toLowerCase()}.png" alt="${conference}"><div class="standings-rail"></div></section>`;}

function broadcastTransition(s,c){if(c.transitionStyle==='matchup')return `<section class="two-team-bumper" data-out-motion="${selectedGraphicMotion(s,c)}" style="--bumper-time:${Math.max(1.2,Math.min(15,Number(c.transitionDuration)||1.2))}s"><div class="bumper-panels">${['away','home'].map(side=>`<div class="bumper-team ${side}" style="${teamStyle(s.teams[side])}"><div class="bumper-folds" aria-hidden="true">${[0,1].map(()=>`<div class="bumper-fold">${Array.from({length:12},(_,i)=>`<i style="--row:${i}"></i>`).join('')}</div>`).join('')}</div><div class="bumper-logo">${logo(s.teams[side])}</div><div class="bumper-edge" aria-hidden="true"></div></div>`).join('')}<div class="bumper-versus"><span>‹</span><b>VS</b><span>›</span></div></div></section>`;const t=s.teams[c.team||'away'],style=c.transitionStyle||'team';return `<section class="broadcast-transition transition-${esc(style)}" style="${teamStyle(t)}"><div class="transition-shutter"></div><div class="transition-emblem">${style==='network'?secondaryMark(s):logo(t)}</div>${style==='person'?`<div class="transition-person"><small>${esc(c.transitionTitle||t.name)}</small><h1>${esc(c.transitionPerson||t.coach)}</h1><p>${esc(c.transitionDetail||'COACHING STAFF')}</p></div>`:''}</section>`;}
const suppressBug=['referee','tiers','standings','transition','scoringdrive','matchup','offense','defense','teamstats','roster','period','final','upcoming','announcers','sponsor','weather','reporter','quarterback','break'];
