function fitGraphicLabels(layer){
 // Fit operator-entered names and alert labels without clipping their last letters.
 for(const el of layer.querySelectorAll('.situation-reveal h1,.staff-plate h1,.td70-name strong,.result-name,.referee-copy h1,.reporter-nameplate h1')){
  el.style.removeProperty('font-size');
  const style=getComputedStyle(el),size=parseFloat(style.fontSize),width=el.clientWidth;
  if(width>0&&el.scrollWidth>width+1){const padding=parseFloat(style.paddingLeft)+parseFloat(style.paddingRight);el.style.fontSize=Math.max(size*.45,size*(width-padding)/Math.max(1,el.scrollWidth-padding))+'px';}
  if(el.matches('.reporter-nameplate h1')){for(let i=0;i<4&&el.scrollWidth>el.clientWidth;i++){const size=parseFloat(getComputedStyle(el).fontSize);el.style.fontSize=(size*Math.min(.98,(el.clientWidth-16)/el.scrollWidth))+'px';}}
 }
}
function freezeGraphicFrame(source,clone){
 const original=[...source.querySelectorAll('*')],copies=[...clone.querySelectorAll('*')];
 original.forEach((node,i)=>{const style=getComputedStyle(node),target=copies[i];for(const key of ['opacity','transform','translate','clip-path','visibility','display'])target.style.setProperty(key,style.getPropertyValue(key),'important');target.style.setProperty('animation','none','important');});
}
function animateLineupUpdate(layer,oldContent,c,changed){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const face=layer.querySelector('.lineup-ribbon-face'),content=face.firstElementChild;
 if(!changed){content.animate([{opacity:0},{opacity:1}],{duration:160,easing:'linear'});return;}
 oldContent.classList.add('lineup-outgoing');oldContent.setAttribute('aria-hidden','true');face.append(oldContent);
 if((c.lineupPhase||'title')==='title'){
  oldContent.animate([{transform:'translateY(0)'},{transform:'translateY(115%)'}],{duration:160,easing:'ease-in',fill:'forwards'});
  content.animate([{transform:'translateY(120%)'},{transform:'translateY(0)'}],{duration:150,delay:600,easing:'ease-out',fill:'both'});
 }else{
  oldContent.animate([{clipPath:'inset(0 0 0 0)'},{clipPath:'inset(0 100% 0 0)'}],{duration:420,easing:'linear',fill:'forwards'});
  const wipe=document.createElement('div');wipe.className='lineup-update-wipe';wipe.setAttribute('aria-hidden','true');face.append(wipe);
  wipe.animate([{left:'100%'},{left:'-24%'}],{duration:420,easing:'linear',fill:'both'});
  content.animate([{transform:'translateX(110%)'},{transform:'translateX(0)'}],{duration:720,delay:100,easing:'cubic-bezier(.16,.65,.3,1)',fill:'both'});
  content.querySelectorAll(':scope > div').forEach((name,i)=>name.animate([{opacity:0,transform:'translateX(45px)'},{opacity:1,transform:'translateX(0)'}],{duration:240,delay:260+i*75,easing:'ease-out',fill:'both'}));
 }
 layer._lineupUpdateTimer=setTimeout(()=>face.querySelectorAll('.lineup-outgoing,.lineup-update-wipe').forEach(el=>el.remove()),850);
}
function delayGraphicMotion(el,ms){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(const a of el.getAnimations({subtree:true})){const timing=a.effect.getTiming();a.effect.updateTiming({delay:(timing.delay||0)+ms});}el.animate([{visibility:'hidden'},{visibility:'visible'}],{duration:ms,easing:'steps(1,end)'});if(el.classList.contains('bug-enter')||el.classList.contains('bug-return'))finishBugEntrance(el);}
function animateScorebugOut(bug,motion){
 clearTimeout(bug._motionTimer);
 const currentOpacity=getComputedStyle(bug).opacity,currentTransform=getComputedStyle(bug.querySelector('.scorebug')).transform;
 // Stop entry effects and legacy CSS exits; the selected exit owns this timeline.
 bug.getAnimations({subtree:true}).forEach(a=>a.cancel());
 bug.dataset.motion=motion;bug.classList.remove('bug-enter','bug-return');bug.classList.add('bug-exit','managed-exit');
 const fade=motion==='fade',reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const target=fade?bug:bug.querySelector('.scorebug');
 if(fade)bug._exitPose=bug.querySelector('.scorebug').animate([{transform:currentTransform},{transform:currentTransform}],{duration:160,fill:'both'});
 const frames=fade?[{opacity:currentOpacity},{opacity:0}]:[{transform:currentTransform,offset:0},{transform:'scale(1,.025)',offset:.7},{transform:'scale(0,.025)',offset:1}];
 bug._exitMotion=target.animate(frames,{duration:reduced?0:fade?160:520,easing:fade?'linear':'cubic-bezier(.55,.05,.8,.45)',fill:'both'});
 bug._exitMotion.onfinish=()=>{if(bug.classList.contains('bug-exit'))bug.remove();};
}
function bugExitDuration(bug){return bug?.dataset.motion==='fade'||matchMedia('(prefers-reduced-motion: reduce)').matches?180:540;}
function finishBugEntrance(bug){
 clearTimeout(bug._motionTimer);
 // Include queued entrance delays so returning from a lineup cannot cut off the wipe.
 const remaining=bug.getAnimations({subtree:true}).reduce((ms,a)=>{const end=Number(a.effect.getComputedTiming().endTime),now=Number(a.currentTime)||0;return Number.isFinite(end)?Math.max(ms,end-now):ms;},0);
 bug._motionTimer=setTimeout(()=>bug.classList.remove('bug-enter','bug-return'),Math.max(0,remaining)+34);
}
// Keep the existing scorebug DOM so flags, strip visibility and timeout changes transition in place.
// Capture the rendered position before changing classes: interrupted entrances must not snap.
function animateQBDock(dock,out,from){
 const bar=dock.querySelector('.qb-live-bar'),style=getComputedStyle(bar);
 from=from||{transform:style.transform,opacity:style.opacity};
 dock._dockMotion?.cancel();clearTimeout(dock._exitTimer);
 dock.classList.toggle('qb-live-out',out);
 // The legacy CSS exit must not compete with the position-preserving animation.
 bar.getAnimations().forEach(animation=>animation.cancel());
 const fade=dock.dataset.motion==='fade',reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const target=fade?{transform:'none',opacity:out?0:1}:{transform:out?`translateX(${dock.classList.contains('dock-home')?'-':''}100%)`:'translateX(0)',opacity:1};
 const duration=reduced?0:fade?160:300;
 const motion=bar.animate([from,target],{duration,easing:fade?'linear':out?'cubic-bezier(.4,0,.8,1)':'cubic-bezier(.2,.65,.3,1)',fill:'both'});
 motion.currentTime=0;dock._dockMotion=motion;
 motion.onfinish=()=>{if(dock._dockMotion!==motion)return;if(out&&dock.classList.contains('qb-live-out'))dock.remove();else{motion.cancel();dock._dockMotion=null;}};
}
function morph(node,next){
 if(node.nodeType!==next.nodeType||node.nodeName!==next.nodeName){node.replaceWith(next.cloneNode(true));return;}
 if(node.nodeType===Node.TEXT_NODE){if(node.textContent!==next.textContent)node.textContent=next.textContent;return;}
 if(node.nodeType!==Node.ELEMENT_NODE)return;
 for(const a of [...node.attributes])if(!next.hasAttribute(a.name))node.removeAttribute(a.name);
 for(const a of [...next.attributes])if(node.getAttribute(a.name)!==a.value)node.setAttribute(a.name,a.value);
 const old=[...node.childNodes],fresh=[...next.childNodes];
 for(let i=0;i<Math.max(old.length,fresh.length);i++){if(!fresh[i])old[i].remove();else if(!old[i])node.append(fresh[i].cloneNode(true));else morph(old[i],fresh[i]);}
}
export function updateClocks(root,s,now=Date.now()/1000){root.querySelectorAll('.score-add').forEach(el=>{if(Number(el.dataset.expires)<=now)el.remove();});root.querySelectorAll('[data-game-clock]').forEach(el=>el.textContent=clockText(s.game.clock,now));root.querySelectorAll('[data-play-clock]').forEach(el=>{const n=clockSeconds(s.game.playClock,now);el.textContent=n;const urgent=n<=5;el.classList.toggle('urgent',urgent);if(urgent&&!el._wasUrgent&&(!s.game.bottomStatus||s.game.bottomStatus==='LIVE')&&s.game.showPlayClock&&s.game.showInfo!==false&&!matchMedia('(prefers-reduced-motion: reduce)').matches){el._warningMotion?.cancel();el._warningMotion=el.animate([{transform:'translateY(0) scale(1)'},{transform:'translateY(-10px) scale(1.16)',offset:.35},{transform:'translateY(2px) scale(1.03)',offset:.72},{transform:'translateY(0) scale(1)'}],{duration:340,easing:'ease-out'});}if(!urgent)el._warningMotion?.cancel();el._wasUrgent=urgent;});}
export function fitStage(stage){const parent=stage.parentElement;new ResizeObserver(()=>{stage.style.transform=`scale(${parent.clientWidth/1920})`;}).observe(parent);}
